-- Canonical Free 200 vocabulary cutover.
-- Lin authorized one active 200-record catalog; every prior extra row becomes inactive history.
-- No row is deleted. Original game_words bytes/rank are captured in history_record/history_rank for rollback.

begin;

lock table public.game_words in share row exclusive mode;

alter table public.game_words
  add column if not exists content_key text,
  add column if not exists spelling_th text,
  add column if not exists audio_status text,
  add column if not exists type text,
  add column if not exists subcategory text,
  add column if not exists access_tier text,
  add column if not exists catalog_version text,
  add column if not exists record_hash text,
  add column if not exists canonical_record jsonb,
  add column if not exists status text,
  add column if not exists history_rank integer,
  add column if not exists history_record jsonb;

update public.game_words
set content_key = word || '@' || level
where content_key is null;

do $precheck$
begin
  if (select count(*) from public.game_words) <> 735 then
    raise exception 'expected 735 pre-cutover game_words rows';
  end if;
  if exists (select 1 from public.game_words where content_key is null) then
    raise exception 'game_words content_key backfill failed';
  end if;
end
$precheck$;

